  'settings.whatsapp.webhookUrl': 'Öffentliche Webhook-URL',
  'settings.whatsapp.webhookUrlHint': 'Wo der Evolution-Server dieses Panel erreicht — die GANZE Adresse, endend auf /api/whatsapp-webhook. Geben Sie nur den Host an, ergänzt das Panel den Pfad. Sie muss aus dem Internet erreichbar sein: Das Panel kann den Hostnamen Ihres Tunnels oder Reverse-Proxys nicht erraten.',
  'settings.whatsapp.portalUrl': 'URL des Kundenportals',
  'settings.whatsapp.portalUrlHint': 'Wo Teilnehmer das Kundenportal von außen erreichen. Diesen Link schickt der Bot für alles, was ein Passwort braucht — das WLAN-Passwort, den Netzwerknamen ändern, die ONT neu starten. Bleibt es leer, übergibt der Bot an einen Menschen, statt einen Link zu senden, der nichts öffnet. Es ist nicht die Adresse darüber: das Portal ist eine eigene App auf einem eigenen Port, sofern kein Reverse-Proxy beide hinter denselben Hostnamen stellt.',
  'settings.whatsapp.botEnabled': 'Automatische Antworten (Bot)',
  'settings.whatsapp.botEnabledHint': 'Antwortet selbstständig: Menü mit Rechnungskopie, Verbindungsstatus und „mit einem Mitarbeiter sprechen“. Sendet nie Passwörter und schweigt, solange ein Operator im Gespräch ist.',
  'settings.whatsapp.botUnlockEnabled': 'Bot darf Vertrauensfreischaltung beantragen',
  'settings.whatsapp.botUnlockEnabledHint': 'Ist der Vertrag gesperrt, zeigt das Menü Option 4 und der Bot beantragt die Vertrauensfreischaltung beim SGP, das entscheidet. Jede Anfrage wird protokolliert.',
  'settings.whatsapp.allowedHosts': 'Zugelassene Server',
  'settings.whatsapp.allowedHostsHint': 'Einer pro Zeile. Leer lassen, um jeden öffentlichen Server zuzulassen; interne Adressen werden immer blockiert. Für Subdomains *.domain.com verwenden.',
  'settings.whatsapp.managedUrl': 'URL des verwalteten Servers',
  'settings.whatsapp.managedUrlHint': 'Optional. Wenn gesetzt, verbinden Bedienende Nummern ohne eine Serveradresse einzugeben.',
  'settings.whatsapp.adminKey': 'Admin-Schlüssel des Servers',
  'settings.whatsapp.adminKeyHint': 'Der AUTHENTICATION_API_KEY deines Evolution-Servers. Leer lassen, um den gespeicherten zu behalten.',
