  'settings.whatsapp.rateLimit': 'Nachrichten pro Minute',
  'settings.whatsapp.rateLimitHint': 'Obergrenze für ausgehende Nachrichten, gemeinsam genutzt von Kampagnen und Warnungen.',
  'settings.whatsapp.bulkPace': 'Takt der automatischen Nachrichten',
